// AUTO-GENERATED by Bloxks — do not edit. Overwritten on every build.
// Remote paywall engine (pure logic). Interprets a paywall description; never runs downloaded code.

/** Version du moteur : le serveur n'envoie que des paywalls dont minRenderer <= RENDERER_VERSION. */
export const RENDERER_VERSION = 1

const NODE_TYPES = ['stack', 'text', 'image', 'icon', 'app_icon', 'spacer', 'feature_list', 'package', 'purchase_button', 'button', 'disclosure']
const ACTIONS = ['close', 'restore', 'terms', 'privacy', 'manage']

export type ColorPair = { light: string; dark?: string }
export type PaywallNode = { type: string; [key: string]: any }
export type PaywallDocument = {
  schemaVersion: number
  minRenderer: number
  defaultLocale: string
  links: { terms: string; privacy: string }
  root: PaywallNode
  footer?: PaywallNode
  localizations: Record<string, Record<string, string>>
}

/** Une offre telle que le store la vend : prix réel, devise, période ISO 8601, essai gratuit. */
export type EnginePackage = {
  productId: string
  title: string
  price: number
  priceString: string
  currency: string
  /** P1W, P1M, P3M, P1Y… null = achat unique. */
  period: string | null
  /** Durée de l'essai gratuit (P3D, P1W…), null sans essai. */
  trial: string | null
  consumable?: boolean
}

export type EngineContext = { locale: string; appName: string; store: 'apple' | 'google' | 'web'; packages: EnginePackage[] }

export type Prepared =
  | { ok: true; paywall: PaywallDocument; locale: string; packages: EnginePackage[]; defaultProductId: string }
  | { ok: false; reason: 'invalid' | 'schema' | 'renderer' | 'no_package' }

// ------------------------------------------------------------ langues -----

type Words = { day: [string, string]; week: [string, string]; month: [string, string]; year: [string, string]; free: string; every: string }
const WORDS: Record<string, Words> = {
  fr: { day: ['jour', 'jours'], week: ['semaine', 'semaines'], month: ['mois', 'mois'], year: ['an', 'ans'], free: 'gratuit', every: '/' },
  en: { day: ['day', 'days'], week: ['week', 'weeks'], month: ['month', 'months'], year: ['year', 'years'], free: 'free', every: '/' },
  es: { day: ['día', 'días'], week: ['semana', 'semanas'], month: ['mes', 'meses'], year: ['año', 'años'], free: 'gratis', every: '/' },
  de: { day: ['Tag', 'Tage'], week: ['Woche', 'Wochen'], month: ['Monat', 'Monate'], year: ['Jahr', 'Jahre'], free: 'kostenlos', every: '/' },
  it: { day: ['giorno', 'giorni'], week: ['settimana', 'settimane'], month: ['mese', 'mesi'], year: ['anno', 'anni'], free: 'gratis', every: '/' },
  pt: { day: ['dia', 'dias'], week: ['semana', 'semanas'], month: ['mês', 'meses'], year: ['ano', 'anos'], free: 'grátis', every: '/' },
}

function lang(locale: string): string {
  const base = String(locale || 'en').slice(0, 2).toLowerCase()
  return WORDS[base] ? base : 'en'
}

/** Langue du paywall : la première langue du téléphone qu'il propose, sinon sa langue par défaut. */
export function pickLocale(doc: PaywallDocument, deviceLocales: string[]): string {
  const available = Object.keys(doc.localizations || {})
  for (const raw of deviceLocales || []) {
    const tag = String(raw || '').replace('_', '-')
    if (available.indexOf(tag) >= 0) return tag
    const base = tag.slice(0, 2).toLowerCase()
    const match = available.find((l) => l.slice(0, 2).toLowerCase() === base)
    if (match) return match
  }
  return doc.defaultLocale
}

// ------------------------------------------------------------ durées -----

type Duration = { n: number; unit: 'day' | 'week' | 'month' | 'year' }

export function parseDuration(iso: string | null | undefined): Duration | null {
  const m = /^P(\d+)([DWMY])$/.exec(String(iso || ''))
  if (!m) return null
  const n = Number(m[1])
  if (!(n > 0)) return null
  const unit = m[2] === 'D' ? 'day' : m[2] === 'W' ? 'week' : m[2] === 'M' ? 'month' : 'year'
  return { n: n, unit: unit }
}

/** Durées d'essai du catalogue Bloxks (ONE_WEEK…) → ISO 8601. */
const TRIAL_ISO: Record<string, string> = { THREE_DAYS: 'P3D', ONE_WEEK: 'P1W', TWO_WEEKS: 'P2W', ONE_MONTH: 'P1M', TWO_MONTHS: 'P2M', THREE_MONTHS: 'P3M', SIX_MONTHS: 'P6M', ONE_YEAR: 'P1Y' }
export function trialIso(catalogTrial: string | null | undefined): string | null {
  if (!catalogTrial || catalogTrial === 'none') return null
  return TRIAL_ISO[catalogTrial] || (parseDuration(catalogTrial) ? catalogTrial : null)
}

/** « 1 semaine », « 3 mois », « 7 days ». */
export function durationLabel(iso: string | null, locale: string): string {
  const d = parseDuration(iso)
  if (!d) return ''
  const w = WORDS[lang(locale)][d.unit]
  return d.n + ' ' + (d.n === 1 ? w[0] : w[1])
}

/** Période d'un prix : « mois », « an », « 3 mois ». */
export function periodLabel(iso: string | null, locale: string): string {
  const d = parseDuration(iso)
  if (!d) return ''
  const w = WORDS[lang(locale)][d.unit]
  return d.n === 1 ? w[0] : d.n + ' ' + w[1]
}

/** Nombre de mois couverts par une période (semaine = 12/52 mois). */
function months(iso: string | null): number | null {
  const d = parseDuration(iso)
  if (!d) return null
  if (d.unit === 'year') return d.n * 12
  if (d.unit === 'month') return d.n
  if (d.unit === 'week') return (d.n * 12) / 52
  return (d.n * 12) / 365
}

export function formatMoney(amount: number, currency: string, locale: string): string {
  try {
    return new Intl.NumberFormat(locale, { style: 'currency', currency: currency }).format(amount)
  } catch {
    return amount.toFixed(2) + ' ' + currency
  }
}

function perMonth(p: EnginePackage): number | null {
  const m = months(p.period)
  return m ? p.price / m : null
}

// ------------------------------------------------------- noms d'offre -----

/** Nom lisible d'une offre quand le store n'en donne pas : « Annuel », « Mensuel », « À vie »… */
type Plans = { year: string; month: string; week: string; day: string; months: string; lifetime: string; pack: string }
const PLANS: Record<string, Plans> = {
  fr: { year: 'Annuel', month: 'Mensuel', week: 'Hebdomadaire', day: 'Quotidien', months: '{n} mois', lifetime: 'À vie', pack: 'Pack' },
  en: { year: 'Annual', month: 'Monthly', week: 'Weekly', day: 'Daily', months: '{n} months', lifetime: 'Lifetime', pack: 'Pack' },
  es: { year: 'Anual', month: 'Mensual', week: 'Semanal', day: 'Diario', months: '{n} meses', lifetime: 'De por vida', pack: 'Pack' },
  de: { year: 'Jährlich', month: 'Monatlich', week: 'Wöchentlich', day: 'Täglich', months: '{n} Monate', lifetime: 'Lebenslang', pack: 'Paket' },
  it: { year: 'Annuale', month: 'Mensile', week: 'Settimanale', day: 'Giornaliero', months: '{n} mesi', lifetime: 'A vita', pack: 'Pacchetto' },
  pt: { year: 'Anual', month: 'Mensal', week: 'Semanal', day: 'Diário', months: '{n} meses', lifetime: 'Vitalício', pack: 'Pacote' },
}

export function planLabel(pkg: EnginePackage, locale: string): string {
  const w = PLANS[lang(locale)]
  if (!pkg.period) return pkg.consumable ? w.pack : w.lifetime
  const d = parseDuration(pkg.period)
  if (!d) return w.month
  if (d.unit === 'month' && d.n % 12 === 0) return d.n === 12 ? w.year : w.months.replace('{n}', String(d.n))
  if (d.n === 1) return d.unit === 'year' ? w.year : d.unit === 'month' ? w.month : d.unit === 'week' ? w.week : w.day
  if (d.unit === 'month') return w.months.replace('{n}', String(d.n))
  return durationLabel(pkg.period, locale)
}

/** Identifiant technique (com.app.pro_annual, pro_monthly, annuel:base) plutôt qu'un vrai nom. */
function looksTechnical(title: string, productId: string): boolean {
  const t = title.trim()
  if (!t) return true
  const lower = t.toLowerCase()
  const id = String(productId || '').toLowerCase()
  if (lower === id || id.split(/[.:]/).indexOf(lower) >= 0) return true
  if (/^[\w-]+([.:][\w-]+)+$/.test(t)) return true
  return /^[a-z0-9]+([_-][a-z0-9]+)+$/.test(t)
}

/**
 * Nom affiché par {{ product.name }} : le titre du store, nettoyé (Google Play ajoute
 * « (Nom de l'app) »), sinon le libellé de la période dans la langue du paywall.
 */
export function productName(pkg: EnginePackage, ctx: EngineContext): string {
  let title = String(pkg.title || '').trim()
  const paren = /^(.*\S)\s*\(([^()]*)\)$/.exec(title)
  if (paren && (!ctx.appName || paren[2].trim().toLowerCase() === ctx.appName.trim().toLowerCase())) title = paren[1].trim()
  if (looksTechnical(title, pkg.productId)) return planLabel(pkg, ctx.locale)
  // Deux offres au même titre (« Pro » mensuel et annuel) : la période les distingue.
  const twin = (ctx.packages || []).some((o) => o.productId !== pkg.productId && String(o.title || '').trim().toLowerCase() === String(pkg.title || '').trim().toLowerCase())
  return twin ? planLabel(pkg, ctx.locale) : title
}

// --------------------------------------------------------- typographie -----

/** Interlignage et approche réglés comme iOS : titres serrés, corps aéré. Partagé par l'app et l'aperçu. */
export function typeScale(size: number): { lineHeight: number; letterSpacing: number } {
  const s = size > 0 ? size : 16
  const ratio = s >= 28 ? 1.14 : s >= 20 ? 1.2 : s >= 15 ? 1.3 : 1.36
  const spacing = s >= 28 ? -0.025 * s : s >= 20 ? -0.015 * s : s >= 15 ? -0.2 : 0
  return { lineHeight: Math.round(s * ratio), letterSpacing: Math.round(spacing * 10) / 10 }
}

// --------------------------------------------------------- mise en page -----
// Règles de placement COMMUNES à l'app (React Native) et à l'aperçu du tableau de bord (DOM) :
// les deux étalent ces styles flexbox tels quels (mêmes noms de propriétés des deux côtés).
// Tout est écrit explicitement, car les valeurs par défaut diffèrent : flexShrink vaut 0 en
// React Native et 1 sur le web ; un bloc qui « grandit » remplit la largeur en React Native
// même dans un groupe centré, alors que le web le réduit à son contenu.
// Sens des réglages pour un non-technicien :
//   • « Alignement » d'un groupe vertical = position horizontale des blocs ET alignement des
//     textes qu'il contient (un texte sans alignement propre suit son groupe) ;
//   • « Alignement » d'une rangée = répartition horizontale, blocs centrés en hauteur ;
//   • « Alignement » d'une superposition = position des calques du dessus sur le premier ;
//   • un « Espace » de taille fixe compte dans le sens du groupe (largeur dans une rangée,
//     hauteur dans une colonne) ; sans taille, il prend la place libre ;
//   • dans une rangée, images, offres et espaces souples se partagent la largeur libre.

/** Pictogrammes des blocs icon / feature_list (caractères simples, aucune bibliothèque). */
export const ICON_GLYPHS: Record<string, string> = { check: '✓', star: '★', lock: '🔒', sparkles: '✦', close: '✕', crown: '♛', bolt: '⚡', heart: '♥', shield: '⛨', gift: '🎁' }

/** Ombres douces (0 = aucune, 3 = la plus marquée) : opacité, flou, décalage, élévation Android. */
export const SHADOW_LEVELS: Array<{ opacity: number; radius: number; y: number; elevation: number } | null> = [
  null,
  { opacity: 0.06, radius: 8, y: 2, elevation: 2 },
  { opacity: 0.1, radius: 16, y: 6, elevation: 5 },
  { opacity: 0.16, radius: 24, y: 10, elevation: 10 },
]

export function shadowLevel(level: any) {
  return SHADOW_LEVELS[typeof level === 'number' ? level : 0] || null
}

export function paddingStyle(v: any): Record<string, number> {
  if (typeof v === 'number') return { padding: v }
  if (Array.isArray(v) && v.length === 4) return { paddingTop: v[0], paddingRight: v[1], paddingBottom: v[2], paddingLeft: v[3] }
  return {}
}

/** Contexte d'un bloc : sens de son groupe, alignement de ce groupe, alignement de texte hérité. */
/** textOf : texte brut d'une clé (langue affichée), pour savoir quels textes d'une rangée passent à la ligne. */
export type LayoutParent = { axis: 'v' | 'h' | 'z'; align?: string; textAlign?: string; screen?: 'root' | 'footer'; textOf?: (lid: string) => string }
export const ROOT_PARENT: LayoutParent = { axis: 'v', screen: 'root' }
export const FOOTER_PARENT: LayoutParent = { axis: 'v', screen: 'footer' }

/** Contexte de la racine ou du bas d'écran, avec la lecture des textes du paywall. */
export function screenParent(screen: 'root' | 'footer', textOf: (lid: string) => string): LayoutParent {
  return { axis: 'v', screen: screen, textOf: textOf }
}

const ALIGN_ITEMS: Record<string, string> = { start: 'flex-start', center: 'center', end: 'flex-end', stretch: 'stretch' }
const JUSTIFY_ROW: Record<string, string> = { start: 'flex-start', center: 'center', end: 'flex-end', stretch: 'space-between' }
const JUSTIFY_Z: Record<string, string> = { start: 'flex-start', center: 'center', end: 'flex-end', stretch: 'flex-start' }
const TEXT_ALIGN: Record<string, string> = { start: 'left', center: 'center', end: 'right' }
/** Part égale de la place libre (flex: 1 écrit en entier, identique en React Native et sur le web). */
const GROW = { flexGrow: 1, flexShrink: 1, flexBasis: 0 }

const isTextAlign = (a: any) => a === 'start' || a === 'center' || a === 'end'

/** Alignement de texte d'un bloc : le sien, sinon celui hérité de son groupe, sinon début. */
export function textAlignOf(n: PaywallNode, parent: LayoutParent): string {
  const own = isTextAlign(n.align) ? n.align : isTextAlign(parent.textAlign) ? parent.textAlign : 'start'
  return TEXT_ALIGN[own as string]
}

/** Contexte transmis aux enfants d'un groupe ou d'une offre. */
export function childParent(n: PaywallNode, parent: LayoutParent): LayoutParent {
  const inherited = parent.textAlign
  const textOf = parent.textOf
  if (n.type === 'package') return { axis: n.axis === 'h' ? 'h' : 'v', textAlign: inherited, textOf: textOf }
  if (n.axis === 'h') return { axis: 'h', align: n.align, textAlign: inherited, textOf: textOf }
  return { axis: n.axis === 'z' ? 'z' : 'v', align: n.align, textAlign: isTextAlign(n.align) ? n.align : inherited, textOf: textOf }
}

const flexibleSpacer = (n: PaywallNode) => n.type === 'spacer' && typeof n.size !== 'number'
/** Dans une rangée, ces blocs se partagent la largeur libre. */
const growsInRow = (n: PaywallNode) => flexibleSpacer(n) || n.type === 'image' || n.type === 'package'
/** Alignement effectif d'une liste d'avantages (le sien, sinon celui du groupe). */
const listAlign = (n: PaywallNode, parent: LayoutParent) => (isTextAlign(n.align) ? n.align : isTextAlign(parent.textAlign) ? parent.textAlign : 'start')

/**
 * Le bloc occupe-t-il toute la largeur disponible ? Vrai pour une image, une offre, une liste
 * d'avantages alignée au début, et tout groupe qui en contient une (ou une rangée avec un espace souple).
 * React Native le fait de lui-même ; on l'écrit (alignSelf: stretch) pour que le web fasse pareil.
 */
export function fillsWidth(n: PaywallNode, parent: LayoutParent): boolean {
  // Une image et une carte d'offre occupent toujours toute la largeur, même dans un groupe centré.
  if (n.type === 'image' || n.type === 'package') return true
  if (n.type === 'feature_list') return listAlign(n, parent) === 'start'
  if (n.type !== 'stack' && n.type !== 'package') return false
  const kids: PaywallNode[] = Array.isArray(n.children) ? n.children : []
  const cp = childParent(n, parent)
  if (n.type === 'stack' && n.axis === 'z') return kids.length > 0 && fillsWidth(kids[0], cp)
  if (cp.axis === 'h') return kids.some((c) => growsInRow(c) || fillsWidth(c, cp))
  return kids.some((c) => fillsWidth(c, cp))
}

const FIXED = ['icon', 'app_icon']
/** Au-delà, un texte de rangée est « long » : c'est lui qui passe à la ligne (une variable compte 8 signes). */
const SHORT_TEXT = 18

/**
 * Le bloc peut-il se resserrer dans une rangée ? Seuls les textes longs (et les groupes qui en
 * contiennent) passent à la ligne : un prix ou un libellé court garde sa ligne, au lieu de se
 * couper parce que son voisin est long. Sans lecture des textes, tout texte peut se resserrer.
 */
function shrinksInRow(n: PaywallNode, parent: LayoutParent): boolean {
  if (n.type === 'feature_list' || n.type === 'disclosure') return true
  if (n.type === 'text' || n.type === 'button' || n.type === 'purchase_button') {
    if (!parent.textOf) return true
    const raw = String(parent.textOf(n.lid) || '')
    return raw.replace(/\{\{[^{}]*\}\}/g, '########').length > SHORT_TEXT
  }
  if (n.type !== 'stack' && n.type !== 'package') return false
  const cp = childParent(n, parent)
  return (Array.isArray(n.children) ? n.children : []).some((c: PaywallNode) => shrinksInRow(c, cp))
}

/** Placement d'un bloc dans son groupe (ce que le groupe lui laisse comme place). */
function placement(n: PaywallNode, parent: LayoutParent): Record<string, any> {
  if (parent.screen === 'root') return { flexGrow: 1, flexShrink: 0 }
  if (parent.screen === 'footer') return { flexShrink: 0 }
  if (parent.axis === 'h') {
    if (growsInRow(n) || fillsWidth(n, parent)) return Object.assign({}, GROW, { minWidth: 0 })
    if (FIXED.indexOf(n.type) >= 0 || n.type === 'spacer') return { flexShrink: 0 }
    // Un texte long passe à la ligne au lieu de sortir de l'écran ; un texte court garde sa ligne.
    return shrinksInRow(n, parent) ? { flexShrink: 1, minWidth: 0 } : { flexShrink: 0 }
  }
  // Colonne : rien ne s'écrase en hauteur (le contenu défile), un espace souple prend la place libre.
  if (flexibleSpacer(n)) return Object.assign({}, GROW)
  const out: Record<string, any> = { flexShrink: 0 }
  if (fillsWidth(n, parent)) out.alignSelf = 'stretch'
  else if (n.type === 'feature_list') out.alignSelf = listAlign(n, parent) === 'end' ? 'flex-end' : 'center'
  return out
}

/**
 * Style flexbox d'un bloc : sa place dans son groupe + la disposition de son contenu.
 * Les couleurs, bordures, ombres et polices restent propres à chaque moteur de dessin.
 */
export function layoutStyle(n: PaywallNode, parent: LayoutParent): Record<string, any> {
  const out: Record<string, any> = placement(n, parent)
  const gap = typeof n.spacing === 'number' ? n.spacing : 0
  switch (n.type) {
    case 'stack':
      if (n.axis === 'z') return Object.assign(out, { position: 'relative', flexDirection: 'column', alignItems: 'stretch' })
      if (n.axis === 'h') return Object.assign(out, { flexDirection: 'row', alignItems: 'center', justifyContent: JUSTIFY_ROW[n.align] || 'flex-start', gap: gap })
      return Object.assign(out, { flexDirection: 'column', alignItems: ALIGN_ITEMS[n.align] || 'stretch', justifyContent: 'flex-start', gap: gap })
    case 'package':
      return Object.assign(out, n.axis === 'h'
        ? { flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-start', gap: gap }
        : { flexDirection: 'column', alignItems: 'stretch', justifyContent: 'flex-start', gap: gap })
    case 'text':
    case 'button':
    case 'disclosure':
      return Object.assign(out, { textAlign: textAlignOf(n, parent) })
    case 'purchase_button': {
      const a = isTextAlign(n.align) ? n.align : 'center'
      return Object.assign(out, { flexDirection: 'column', alignItems: ALIGN_ITEMS[a], justifyContent: 'center' })
    }
    case 'feature_list':
      return Object.assign(out, { flexDirection: 'column', gap: typeof n.spacing === 'number' ? n.spacing : 8 })
    case 'image':
      return Object.assign(out, parent.axis === 'h' ? {} : { width: '100%' }, { aspectRatio: typeof n.aspect === 'number' && n.aspect > 0 ? n.aspect : 1.6 })
    case 'spacer':
      if (typeof n.size !== 'number') return out
      return Object.assign(out, parent.axis === 'h' ? { width: n.size } : { height: n.size })
  }
  return out
}

/** Calques d'une superposition : le premier donne la taille, les suivants le recouvrent. */
export function layerStyle(n: PaywallNode, index: number): Record<string, any> {
  const base = { flexDirection: 'column', alignItems: ALIGN_ITEMS[n.align] || 'stretch', justifyContent: JUSTIFY_Z[n.align] || 'flex-start' }
  if (index === 0) return base
  // Mêmes marges que le premier calque : « Marge intérieure » s'applique à tous les calques.
  return Object.assign({ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }, paddingStyle(n.padding), base)
}

/** Pictogramme : boîte fixe (pastille ronde si fond), caractère centré. */
export function glyphLayout(size: number, withBackground: boolean) {
  const s = size > 0 ? size : 20
  const line = Math.round(s * 1.2)
  const d = withBackground ? Math.round(s * 1.75) : line
  return {
    box: { width: d, height: d, flexShrink: 0, alignItems: 'center', justifyContent: 'center', borderRadius: withBackground ? d / 2 : 0 },
    char: { fontSize: s, lineHeight: line, textAlign: 'center' },
  }
}

/** Liste d'avantages : une rangée par avantage, pictogramme puis texte. */
export function featureLayout(n: PaywallNode, parent: LayoutParent) {
  const size = typeof n.size === 'number' ? n.size : 16
  const full = listAlign(n, parent) === 'start'
  return {
    glyphSize: n.iconBackground ? Math.round(size * 0.72) : size,
    row: { flexDirection: 'row', alignItems: n.iconBackground ? 'center' : 'flex-start', gap: 12 },
    // Liste centrée : le bloc se resserre sur ses textes, alignés entre eux à gauche.
    text: full ? Object.assign({}, GROW, { minWidth: 0, textAlign: 'left' }) : { flexShrink: 1, minWidth: 0, textAlign: 'left' },
  }
}

/** Initiale de l'app (tuile de repli quand l'app n'a pas encore d'icône). */
export function appInitial(appName: string): string {
  const m = /[A-Za-z0-9À-ÖØ-öø-ÿ]/.exec(String(appName || ''))
  return m ? m[0].toUpperCase() : '★'
}

// ---------------------------------------------------------- variables -----

const VARIABLE_RE = /\{\{\s*([^{}]*?)\s*\}\}/g

/** Valeur d'une variable pour une offre ('' si elle n'a pas de sens pour cette offre). */
export function variableValue(name: string, pkg: EnginePackage | null, ctx: EngineContext): string {
  if (name === 'app.name') return ctx.appName || ''
  if (!pkg) return ''
  const locale = ctx.locale
  switch (name) {
    case 'product.name': return productName(pkg, ctx)
    case 'product.price': return pkg.priceString
    case 'product.period': return periodLabel(pkg.period, locale)
    case 'product.price_per_period': return pkg.period ? pkg.priceString + ' ' + WORDS[lang(locale)].every + ' ' + periodLabel(pkg.period, locale) : pkg.priceString
    case 'product.price_per_month': {
      const v = perMonth(pkg)
      return v === null ? pkg.priceString : formatMoney(v, pkg.currency, locale)
    }
    case 'product.price_per_week': {
      const v = perMonth(pkg)
      return v === null ? pkg.priceString : formatMoney((v * 12) / 52, pkg.currency, locale)
    }
    case 'product.offer_price': return pkg.trial ? WORDS[lang(locale)].free : ''
    case 'product.offer_period': return durationLabel(pkg.trial, locale)
    case 'product.relative_discount': {
      // Économie par rapport à l'offre la plus chère ramenée au mois, arrondie vers le bas.
      const mine = perMonth(pkg)
      const all = ctx.packages.map(perMonth).filter((x): x is number => x !== null)
      if (mine === null || all.length < 2) return ''
      const max = Math.max.apply(null, all)
      const pct = Math.floor((1 - mine / max) * 100)
      return pct > 0 ? pct + ' %' : ''
    }
  }
  return ''
}

export function interpolate(text: string, pkg: EnginePackage | null, ctx: EngineContext): string {
  return String(text || '').replace(VARIABLE_RE, (_m, name) => variableValue(String(name), pkg, ctx))
}

/** Texte d'une clé : langue choisie, sinon langue par défaut, sinon rien. */
export function textFor(doc: PaywallDocument, locale: string, lid: string): string {
  const table = doc.localizations[locale]
  if (table && typeof table[lid] === 'string') return table[lid]
  const base = doc.localizations[doc.defaultLocale]
  return base && typeof base[lid] === 'string' ? base[lid] : ''
}

// ---------------------------------------------------------- overrides -----

const FROZEN = ['type', 'children', 'product', 'action', 'items', 'overrides', 'selectedByDefault']

/** Le bloc tel qu'il s'affiche : overrides appliqués quand TOUTES leurs conditions sont vraies. */
export function resolveNode(node: PaywallNode, state: { selected: boolean; introOffer: boolean }): PaywallNode {
  const list = Array.isArray(node.overrides) ? node.overrides : []
  let out: PaywallNode = node
  for (const o of list) {
    if (!o || !Array.isArray(o.when) || !o.props) continue
    const on = o.when.every((c: string) => (c === 'selected' ? state.selected : c === 'intro_offer' ? state.introOffer : false))
    if (!on) continue
    const props: Record<string, any> = {}
    for (const k of Object.keys(o.props)) if (FROZEN.indexOf(k) < 0) props[k] = o.props[k]
    out = Object.assign({}, out, props)
  }
  return out
}

export function colorOf(pair: ColorPair | undefined, scheme: 'light' | 'dark' | null | undefined, fallback?: string): string | undefined {
  if (!pair || typeof pair.light !== 'string') return fallback
  return scheme === 'dark' && typeof pair.dark === 'string' ? pair.dark : pair.light
}

// ------------------------------------------------------------ prepare -----

function clean(node: any, available: Record<string, boolean>, seen: Record<string, boolean>, depth: number): PaywallNode | null {
  if (!node || typeof node !== 'object' || NODE_TYPES.indexOf(node.type) < 0 || depth > 12) return null
  if (node.type === 'package') {
    if (!available[node.product] || seen[node.product]) return null
    seen[node.product] = true
  }
  if (node.type === 'button' && ACTIONS.indexOf(node.action) < 0) return null
  if (node.type === 'stack' || node.type === 'package') {
    const kids = Array.isArray(node.children) ? node.children : []
    const children: PaywallNode[] = []
    for (const c of kids) {
      const k = clean(c, available, seen, depth + 1)
      if (k) children.push(k)
    }
    return Object.assign({}, node, { children: children })
  }
  return node
}

function collectProducts(node: PaywallNode | undefined, out: string[], defaults: string[]) {
  if (!node) return
  if (node.type === 'package') {
    out.push(node.product)
    if (node.selectedByDefault) defaults.push(node.product)
  }
  if (Array.isArray(node.children)) for (const c of node.children) collectProducts(c, out, defaults)
}

/**
 * Prépare un paywall pour l'affichage : contrôles de version, blocs inconnus retirés, offres
 * que le store ne vend pas retirées. Inutilisable (aucune offre restante…) → ok: false.
 */
export function prepare(doc: any, packages: EnginePackage[], deviceLocales: string[]): Prepared {
  if (!doc || typeof doc !== 'object' || !doc.root || !doc.localizations || !doc.links) return { ok: false, reason: 'invalid' }
  if (doc.schemaVersion !== 1) return { ok: false, reason: 'schema' }
  if (!(doc.minRenderer <= RENDERER_VERSION)) return { ok: false, reason: 'renderer' }
  const available: Record<string, boolean> = {}
  for (const p of packages || []) available[p.productId] = true
  const seen: Record<string, boolean> = {}
  const root = clean(doc.root, available, seen, 1)
  const footer = doc.footer ? clean(doc.footer, available, seen, 1) : null
  if (!root) return { ok: false, reason: 'invalid' }
  const paywall: PaywallDocument = Object.assign({}, doc, { root: root, footer: footer || undefined })
  const shown: string[] = []
  const defaults: string[] = []
  collectProducts(paywall.root, shown, defaults)
  collectProducts(paywall.footer, shown, defaults)
  if (shown.length === 0) return { ok: false, reason: 'no_package' }
  return {
    ok: true,
    paywall: paywall,
    locale: pickLocale(paywall, deviceLocales),
    packages: (packages || []).filter((p) => shown.indexOf(p.productId) >= 0),
    defaultProductId: defaults[0] || shown[0],
  }
}

