/** Mentions légales de l'offre choisie, dans la langue du paywall. Jamais éditables. */
export function disclosureText(pkg: EnginePackage | null, ctx: EngineContext): string {
  if (!pkg) return ''
  const l = LEGAL[lang(ctx.locale)]
  if (!pkg.period) return pkg.consumable ? l.consumable : l.once
  const account = l.account[ctx.store] || l.account.web
  const parts: string[] = []
  if (pkg.trial) parts.push(l.trial.replace('{trial}', durationLabel(pkg.trial, ctx.locale)).replace('{price}', variableValue('product.price_per_period', pkg, ctx)))
  parts.push(l.renew.split('{account}').join(account))
  return parts.join(' ')
}

