/**
 * Paywall de secours, toujours conforme : liste les offres du store avec prix, durée, essai,
 * restauration, CGU, confidentialité, fermeture et mentions légales. Utilisé quand le paywall
 * distant est inutilisable (format trop récent, aucune offre en vente…).
 */
export function basicPaywall(packages: EnginePackage[], links: { terms: string; privacy: string }): PaywallDocument {
  const text = (lid: string, size: number, weight?: number) => ({ type: 'text', lid: lid, size: size, weight: weight || 400, color: { light: '#111113', dark: '#FFFFFF' } })
  const muted = { light: '#60646C', dark: '#B0B4BA' }
  const pkgs = (packages || []).map((p, i) => ({
    type: 'package', product: p.productId, selectedByDefault: i === 0, axis: 'v', spacing: 4, padding: 16, radius: 16,
    // Même épaisseur choisie ou non : la carte ne « saute » pas d'un pixel quand on la touche.
    border: { width: 2, color: { light: '#E0E1E6', dark: '#3A3A40' } },
    overrides: [{ when: ['selected'], props: { border: { width: 2, color: { light: '#2F6BFF', dark: '#6B95FF' } } } }],
    children: [text('name', 16, 600), text(p.trial ? 'trial' : 'price', 15, 500)],
  }))
  const link = (lid: string, action: string) => ({ type: 'button', lid: lid, action: action, size: 13, color: muted })
  return {
    schemaVersion: 1,
    minRenderer: 1,
    defaultLocale: 'en',
    links: links,
    root: {
      type: 'stack', axis: 'v', spacing: 16, padding: [16, 20, 16, 20], background: { light: '#FFFFFF', dark: '#0B0B0F' },
      children: [
        { type: 'stack', axis: 'h', align: 'end', children: [{ type: 'spacer' }, link('close', 'close')] },
        { type: 'stack', axis: 'v', align: 'center', children: [{ type: 'app_icon', size: 72, radius: 16, shadow: 2, background: { light: '#2F6BFF' }, color: { light: '#FFFFFF' } }] },
        Object.assign(text('title', 28, 800), { align: 'center' }),
        { type: 'stack', axis: 'v', spacing: 10, children: pkgs },
      ],
    },
    footer: {
      type: 'stack', axis: 'v', spacing: 10, padding: [12, 20, 16, 20], background: { light: '#FFFFFF', dark: '#0B0B0F' },
      children: [
        { type: 'purchase_button', lid: 'cta', size: 17, weight: 700, color: { light: '#FFFFFF' }, background: { light: '#2F6BFF' }, radius: 999, padding: 16, overrides: [{ when: ['intro_offer'], props: { lid: 'cta_trial' } }] },
        { type: 'disclosure', size: 11, color: muted, align: 'center' },
        { type: 'stack', axis: 'h', spacing: 16, align: 'center', children: [link('restore', 'restore'), link('terms', 'terms'), link('privacy', 'privacy')] },
      ],
    },
    localizations: BASIC_TEXTS,
  }
}
